mapper.select:
        SELECT 
            A.BOOKSET_ID as booksetId,
            A.HAPPEN_DATE as happenDate,
            A.BOOK_DATE as bookDate,
            C.BOOKSET_DATE as booksetDate,
            B.STANDARD_CCY as standardCcy,
            A.TASK_ID as taskId,
			b.acct_subject_id as finprodId,
            b.acct_subject_type as finprodType
        FROM BOK_BATCH_TASK_TODO A
        INNER JOIN BOK_BOOKSET B
            ON B.BOOKSET_ID = A.BOOKSET_ID
        LEFT JOIN BOK_BOOKSET_DATE C
            ON C.BOOKSET_ID = A.BOOKSET_ID 
        WHERE
            A.SEQ_NO = #{seqNo}
            AND A.BOOKSET_DATE = #{BOOKSET_DATE}
            AND A.BOOK_DATE = #{BOOK_DATE}
            AND A.HAPPEN_DATE = #{HAPPEN_DATE}
            AND A.TASK_ID = #{taskId}
            AND B.ACCT_SUBJECT_TYPE != #{acctSubjectType}
            AND A.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
